.player-controls{display:grid;grid-template-columns:auto minmax(220px,1fr);gap:10px;padding:14px;border-radius:14px;background:var(--panel);position:relative}.player-controls>.player-filter-row:first-of-type{grid-column:1;grid-row:1}.player-search{grid-column:2;grid-row:1;justify-self:end;width:min(100%,440px)}.player-dfo-row{grid-column:1/-1;display:flex;justify-content:flex-start;align-items:center;margin-top:-2px;margin-bottom:-2px}.player-dfo-top{position:static;justify-self:start;align-self:center;z-index:auto}.player-filter{border-radius:20px;min-height:30px;padding:4px 10px;font-size:11px}.player-filter.selected{background:color-mix(in srgb,#087f8c 14%,var(--panel));color:var(--text);border-color:#087f8c;box-shadow:inset 0 0 0 1px #087f8c}.player-advanced{grid-column:1/-1;width:100%;padding-top:7px}.player-advanced summary{font-size:12px;min-height:24px}.player-advanced-grid{display:grid;grid-template-columns:1fr;gap:8px;padding-top:8px}.player-availability-row{grid-row:2}.player-slicers{grid-row:3;width:100%}.player-slicer{display:flex;align-items:center;gap:12px}.player-slicer>span,.player-filter-row>.filter-label{min-width:82px;font-size:11px;color:var(--muted)}.player-slicer select{width:min(360px,100%);min-height:30px;padding:4px 8px;font-size:12px}.player-assignment-filter{gap:7px}.player-game-cell{font-size:11px;white-space:normal}.player-game-cell strong{display:block}.player-game-cell small{font-size:9px}.player-game-header{min-width:72px}
@media(max-width:650px){.player-controls{grid-template-columns:1fr;padding:10px;gap:8px}.player-controls>.player-filter-row:first-of-type,.player-search,.player-dfo-row{grid-column:1;grid-row:auto}.player-dfo-row{justify-content:flex-start}.player-search{width:100%;max-width:none;justify-self:stretch;min-width:0}.player-buttons{gap:4px}.player-filter{padding:4px 8px}.player-slicer{gap:7px}}
.player-controls>.player-availability-row,.player-main-stats{grid-column:1/-1}.player-controls>.player-filter-row>.filter-label,.player-sort-controls>.filter-label{min-width:108px}.player-controls>.player-availability-row{grid-row:auto}.player-sort-controls{align-items:center;border-top:1px solid var(--line);padding-top:10px}.player-main-stats .player-buttons{gap:5px}.player-goalie-status{display:inline-block;margin-top:4px;padding:2px 5px;border:1px solid;border-radius:5px;font-size:9px;font-weight:700;line-height:1.3;white-space:normal}.player-goalie-confirmed{background:#dcfce7;color:#166534;border-color:#86efac}.player-goalie-likely{background:#fef3c7;color:#92400e;border-color:#fcd34d}.player-goalie-unconfirmed{background:var(--panel);color:var(--muted);border-color:var(--line)}.player-goalie-not-starting{background:#fee2e2;color:#991b1b;border-color:#fca5a5}.player-vegas-odds{display:inline-block;margin-top:4px;margin-left:3px;padding:2px 5px;border:1px solid transparent;border-radius:5px;font-size:9px;font-weight:800;line-height:1.3;white-space:nowrap}.player-vegas-odds-good{background:#dcfce7;color:#166534;border-color:#86efac}.player-vegas-odds-neutral{background:#fef9c3;color:#854d0e;border-color:#fde047}.player-vegas-odds-bad{background:#fee2e2;color:#991b1b;border-color:#fca5a5}html[data-theme="dark"] .player-goalie-confirmed{background:#153e2c;color:#8ce9b4;border-color:#38895e}html[data-theme="dark"] .player-goalie-likely{background:#493d1d;color:#fde68a;border-color:#94772a}html[data-theme="dark"] .player-goalie-not-starting{background:#491e25;color:#fecaca;border-color:#913c47}html[data-theme="dark"] .player-vegas-odds-good{background:#173d27;color:#86efac;border-color:#277344}html[data-theme="dark"] .player-vegas-odds-neutral{background:#45391a;color:#fde68a;border-color:#8d742d}html[data-theme="dark"] .player-vegas-odds-bad{background:#491e25;color:#fecaca;border-color:#913c47}@media(max-width:650px){.player-controls>.player-filter-row>.filter-label,.player-sort-controls>.filter-label{min-width:100%;margin-bottom:2px}.player-sort-controls{gap:6px}.player-dfo-row{margin-top:0;margin-bottom:0}.player-controls{padding-top:10px}}

/* Game details use two compact lines for both skaters and goaltenders. */
.season-player-table .player-game-main{display:flex;align-items:center;justify-content:flex-end;gap:4px;white-space:nowrap;line-height:14px}
.season-player-table .player-game-main strong{display:inline;font-size:10px}
