.player-advanced-section{grid-column:1/-1;position:relative;border-top:1px solid var(--line);padding-top:7px;width:100%}.player-advanced-section .player-advanced{border-top:0;padding-top:0}.player-advanced-section summary{padding-right:120px;min-height:30px}.player-reset-filters{position:absolute;right:0;top:7px;z-index:1}.player-active-filters:empty{display:none}.player-table-scroll{margin-top:12px}.player-name-line{display:flex;align-items:center;gap:4px;min-width:0}
